void getLambdaArgumentTypes(DataTypes & arguments) const override
{
    Adapter::extractNestedTypes(arguments);
    impl.getLambdaArgumentTypes(arguments);
}

DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
{
    if (arguments.empty())
        throw Exception(
            ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
                "Function {} requires at least one argument, passed {}", getName(), arguments.size());

    auto nested_arguments = arguments;
    extractNestedTypesAndColumns(nested_arguments);

    constexpr bool impl_has_get_return_type = requires
    {
        impl.getReturnTypeImpl(nested_arguments);
    };

    DataTypePtr nested_type;
    /// If method is not overloaded in the implementation call default implementation
    /// from IFunction. Here inheritance cannot be used for template parameterized field.
    if constexpr (impl_has_get_return_type)
        nested_type = impl.getReturnTypeImpl(nested_arguments);
    else
        nested_type = dynamic_cast<const IFunction &>(impl).getReturnTypeImpl(nested_arguments);

    if constexpr (std::is_same_v<Impl, FunctionArrayMap> || std::is_same_v<Impl, FunctionArrayConcat>)
    {
        /// Check if nested type is Array(Tuple(key, value))
        const auto * type_array = typeid_cast<const DataTypeArray *>(nested_type.get());
        if (!type_array)
            throw Exception(ErrorCodes::BAD_ARGUMENTS,
                "Expected Array(Tuple(key, value)) type, got {}", nested_type->getName());

        const auto * type_tuple = typeid_cast<const DataTypeTuple *>(type_array->getNestedType().get());
        if (!type_tuple)
            throw Exception(ErrorCodes::BAD_ARGUMENTS,
                "Expected Array(Tuple(key, value)) type, got {}", nested_type->getName());

        if (type_tuple->getElements().size() != 2)
            throw Exception(ErrorCodes::BAD_ARGUMENTS,
                "Expected Array(Tuple(key, value)) type, got {}", nested_type->getName());

        /// Recreate nested type with explicitly named tuple.
        return Adapter::wrapType(std::make_shared<DataTypeArray>(std::make_shared<DataTypeTuple>(DataTypes{type_tuple->getElement(0), type_tuple->getElement(1)}, Names{"keys", "values"})));
    }
    else
        return Adapter::wrapType(nested_type);
}

struct MapAdapterBase
{
    static void extractNestedTypes(DataTypes & types)
    {
        bool has_map_column = false;
        for (auto & type : types)
        {
            if (const auto * type_map = typeid_cast<const DataTypeMap *>(type.get()))
            {
                has_map_column = true;
                type = Derived::extractNestedType(*type_map);
            }
        }

        if (!has_map_column)
            throw Exception(ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
                "Function {} requires at least one argument of type Map", Name::name);
    }

    static void extractNestedTypesAndColumns(ColumnsWithTypeAndName & arguments)
    {
        bool has_map_column = false;
        for (auto & argument : arguments)
        {
            if (const auto * type_map = typeid_cast<const DataTypeMap *>(argument.type.get()))
            {
                has_map_column = true;
                argument.type = Derived::extractNestedType(*type_map);

                if (argument.column)
                {
                    if (const auto * const_map = checkAndGetColumnConstData<ColumnMap>(argument.column.get()))
                        argument.column = ColumnConst::create(Derived::extractNestedColumn(*const_map), argument.column->size());
                    else
                        argument.column = Derived::extractNestedColumn(assert_cast<const ColumnMap &>(*argument.column));
                }
            }
        }

        if (!has_map_column)
            throw Exception(ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
                "Function {} requires at least one argument of type Map", Name::name);
    }
};

/// Adapter that extracts nested Array(Tuple(key, value)) from Map columns.
template <typename Name, bool returns_map = true>
struct MapToNestedAdapter : public MapAdapterBase<MapToNestedAdapter<Name, returns_map>, Name>
{
    using MapAdapterBase<MapToNestedAdapter, Name>::extractNestedTypes;
    using MapAdapterBase<MapToNestedAdapter, Name>::extractNestedTypesAndColumns;

    /// Functions returning a Map should keep the key/value types (including LowCardinality) of the input.
    static constexpr bool preserve_low_cardinality = returns_map;

    static DataTypePtr extractNestedType(const DataTypeMap & type_map)
    {
        return type_map.getNestedType();
    }

    static ColumnPtr extractNestedColumn(const ColumnMap & column_map)
    {
        return column_map.getNestedColumnPtr();
    }

    static DataTypePtr extractResultType(const DataTypePtr & result_type)
    {
        if constexpr (returns_map)
            return assert_cast<const DataTypeMap &>(*result_type).getNestedType();
        return result_type;
    }

    static DataTypePtr wrapType(DataTypePtr type)
    {
        if constexpr (returns_map)
            return std::make_shared<DataTypeMap>(std::move(type));
        return type;
    }

    static ColumnPtr wrapColumn(ColumnPtr column)
    {
        if constexpr (returns_map)
            return ColumnMap::create(std::move(column));
        return column;
    }
};

/// Adapter for mapEntries. It exposes singular public tuple field names while reusing
/// the Map's existing nested Array(Tuple(...)) column without materializing entries.
template <typename Name>
struct MapEntriesAdapter : public MapAdapterBase<MapEntriesAdapter<Name>, Name>
{
    using MapAdapterBase<MapEntriesAdapter, Name>::extractNestedTypes;
    using MapAdapterBase<MapEntriesAdapter, Name>::extractNestedTypesAndColumns;

    /// mapEntries follows Array semantics and strips nested LowCardinality, like mapKeys/mapValues.
    static constexpr bool preserve_low_cardinality = false;

    static DataTypePtr extractNestedType(const DataTypeMap & type_map)
    {
        return std::make_shared<DataTypeArray>(
            std::make_shared<DataTypeTuple>(type_map.getKeyValueTypes(), Names{"key", "value"}));
    }

    static ColumnPtr extractNestedColumn(const ColumnMap & column_map)
    {
        return column_map.getNestedColumnPtr();
    }

    static DataTypePtr extractResultType(const DataTypePtr & result_type) { return result_type; }
    static DataTypePtr wrapType(DataTypePtr type) { return type; }
    static ColumnPtr wrapColumn(ColumnPtr column) { return column; }
};

DataTypePtr getReturnTypeImpl(const DataTypes & arguments) const override
{
    if ((name == NameEquals::name || name == NameNotEquals::name))
    {
        if (!arguments[0]->isComparableForEquality() || !arguments[1]->isComparableForEquality())
            throw Exception(
                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
                "Illegal types of arguments ({}, {}) of function {}, because some of them are not comparable for equality",
                backQuote(arguments[0]->getName()),
                backQuote(arguments[1]->getName()),
                backQuote(getName()));
    }
    else if (!arguments[0]->isComparable() || !arguments[1]->isComparable())
    {
        throw Exception(
            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
            "Illegal types of arguments ({}, {}) of function {}, because some of them are not comparable",
            backQuote(arguments[0]->getName()),
            backQuote(arguments[1]->getName()),
            backQuote(getName()));
    }

    WhichDataType left(arguments[0].get());
    WhichDataType right(arguments[1].get());

    const DataTypeTuple * left_tuple = checkAndGetDataType<DataTypeTuple>(arguments[0].get());
    const DataTypeTuple * right_tuple = checkAndGetDataType<DataTypeTuple>(arguments[1].get());

    bool both_represented_by_number = arguments[0]->isValueRepresentedByNumber() && arguments[1]->isValueRepresentedByNumber();
    bool has_date = left.isDateOrDate32() || right.isDateOrDate32();

    if (!((both_represented_by_number && !has_date)   /// Do not allow to compare date and number.
        || (left.isStringOrFixedString() || right.isStringOrFixedString())  /// Everything can be compared with string by conversion.
        /// You can compare the date, datetime, or datetime64 and an enumeration with a constant string.
        || ((left.isDate() || left.isDate32() || left.isDateTime() || left.isDateTime64()) && (right.isDate() || right.isDate32() || right.isDateTime() || right.isDateTime64()) && left.idx == right.idx) /// only date vs date, or datetime vs datetime
        || (left.isUUID() && right.isUUID())
        || ((left.isIPv4() || left.isIPv6()) && (right.isIPv4() || right.isIPv6()))
        || (left.isEnum() && right.isEnum() && arguments[0]->getName() == arguments[1]->getName()) /// only equivalent enum type values can be compared against
        || (left_tuple && right_tuple && left_tuple->getElements().size() == right_tuple->getElements().size())
        || (arguments[0]->equals(*arguments[1]))))
    {
        if (!tryGetLeastSupertype(arguments))
        {
            /// Arrays with elements types bigger than 32 bits (e.g. `Array(Int64)` vs
            /// `Array(UInt64)`, can still be compared
            /// element-wise using the accurate scalar comparison.
            const auto * left_array = checkAndGetDataType<DataTypeArray>(arguments[0].get());
            const auto * right_array = checkAndGetDataType<DataTypeArray>(arguments[1].get());
            if (left_array && right_array)
            {
                /// Array element comparison treats inner NULLs as regular comparable values (a NULL
                /// is equal only to another NULL and sorts after every non-NULL value)
                auto left_nested_type = removeLowCardinalityAndNullable(left_array->getNestedType());
                auto right_nested_type = removeLowCardinalityAndNullable(right_array->getNestedType());

                /// Recurse directly instead of going through an overload resolver.
                DataTypePtr element_result_type = getReturnTypeImpl(DataTypes{left_nested_type, right_nested_type});

                /// Reject only aligned string-vs-non-string positions
                bool has_string_vs_non_string = hasAlignedStringVsNonStringElement(left_nested_type, right_nested_type);

                /// The element comparator yields `UInt8` for the mixed signed/unsigned case. For a
                /// nested-`Nullable` composite element (e.g. `Tuple(Nullable(T))`) it yields `Nullable(UInt8)`;
                const bool is_equality = (name == NameEquals::name || name == NameNotEquals::name);
                const bool element_result_ok
                    = WhichDataType(element_result_type.get()).isUInt8()
                    || (is_equality && element_result_type->isNullable()
                        && WhichDataType(removeNullable(element_result_type).get()).isUInt8());
                /// Tested on the unstripped nested types, so the `Nullable` arms stay visible.
                if (element_result_ok && !has_string_vs_non_string
                    && !containsUndecidableNothing(left_array->getNestedType())
                    && !containsUndecidableNothing(right_array->getNestedType()))
                    return std::make_shared<DataTypeUInt8>();
            }

            throw Exception(ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT, "Illegal types of arguments ({}, {})"
                " of function {}", backQuote(arguments[0]->getName()), backQuote(arguments[1]->getName()), backQuote(getName()));
        }
    }

    bool both_tuples = left_tuple && right_tuple;
    if (both_tuples || (left_tuple && right.isStringOrFixedString()) || (left.isStringOrFixedString() && right_tuple))
    {
        auto func = std::make_shared<FunctionToOverloadResolverAdaptor>(std::make_shared<FunctionComparison<Op, Name>>(params));

        bool has_nullable = false;
        bool has_null = false;
        bool has_nothing = false;

        const DataTypeTuple * any_tuple = left_tuple ? left_tuple : right_tuple;
        size_t size = any_tuple->getElements().size();
        for (size_t i = 0; i < size; ++i)
        {
            DataTypePtr element_type = any_tuple->getElement(i);
            if (both_tuples)
            {
                ColumnsWithTypeAndName args = {{nullptr, left_tuple->getElements()[i], ""},
                                               {nullptr, right_tuple->getElements()[i], ""}};
                element_type = func->build(args)->getResultType();
            }
            else
            {
                /// One side is `String`/`FixedString`. At runtime the string is parsed as a tuple
                /// value matching the structure of the tuple side and compared element-wise.
                /// Recursively compute the element-vs-string comparison type so that nested
                /// `Nullable` (or `Nothing`/`Dynamic`/`Variant`) elements transitively propagate
                /// `Nullable` to the outer return type. Without this, e.g.
                /// `Tuple(Tuple(Nullable(String))) <= String` would be inferred as `UInt8`
                /// while the runtime produces `Nullable(UInt8)`, tripping the type-mismatch
                /// assertion in the analyzer's constant-folding path (STID 3344-4a3c).
                const DataTypePtr & string_side_type = left_tuple ? arguments[1] : arguments[0];
                ColumnsWithTypeAndName args = left_tuple
                    ? ColumnsWithTypeAndName{{nullptr, element_type, ""}, {nullptr, string_side_type, ""}}
                    : ColumnsWithTypeAndName{{nullptr, string_side_type, ""}, {nullptr, element_type, ""}};
                element_type = func->build(args)->getResultType();
            }
            has_nullable = has_nullable || element_type->isNullable() || isDynamic(element_type);

            /// Nullable(Nothing)
            has_null = has_null || element_type->onlyNull();

            /// Nothing
            has_nothing = has_nothing || isNothing(element_type);
        }

        // In null-safe cmp mode, return DataTypeUInt8 (null-safe comparison always produces a definite result)
        if (is_null_safe_cmp_mode)
            return std::make_shared<DataTypeUInt8>();

        if (has_nothing)
            return std::make_shared<DataTypeNullable>(std::make_shared<DataTypeUInt8>());
        /// If any element comparison is nullable, return type will also be nullable.
        /// We useDefaultImplementationForNulls, but it doesn't work for tuples.
        if (has_null)
            return std::make_shared<DataTypeNullable>(std::make_shared<DataTypeUInt8>());
        if (has_nullable)
            return std::make_shared<DataTypeNullable>(std::make_shared<DataTypeUInt8>());
    }

    return std::make_shared<DataTypeUInt8>();
}
